"""
    Used in lines_intersection
    from:
    https://stackoverflow.com/questions/20677795/how-do-i-compute-the-intersection-point-of-two-lines-in-python
    """
def line_parameters_xy(pt_1: Any, pt_2: Any) -> object {
    a = pt_1[1] - pt_2[1];
    b = pt_2[0] - pt_1[0];
    c = (pt_1[0] * pt_2[1]) - (pt_2[0] * pt_1[1]);
    return (a, b, -c);
}

"""Calculate shifts from z = 0 for each phase."""
def calc_z_shifts(zphase: Any, zsubstrate: Any, margin: Any) -> object {
    shifts = {};
    shifts['sub_bottom'] = margin;
    sub_bottom_upper_margin = shifts['sub_bottom'] + zsubstrate;
    shifts['phase'] = sub_bottom_upper_margin + margin;
    phase_upper_margin = shifts['phase'] + zphase;
    shifts['sub_top'] = phase_upper_margin + margin;
    sub_top_upper_margin = shifts['sub_top'] + zsubstrate;
    shifts['box_z'] = sub_top_upper_margin + margin;
    return shifts;
}

"""
    Count number of bits needed to store a (positive) integer number.

    >>> countBits(0)
    1
    >>> countBits(1000)
    10
    >>> countBits(44100)
    16
    >>> countBits(18446744073709551615)
    64
    """
def countBits(value: Any) -> object {
    assert (0 <= value);
    count = 1;
    bits = 1;
    while ((1 << bits) <= value) {
        count += bits;
        value >>= bits;
        bits <<= 1;
    }
    while (2 <= value) {
        if (bits != 1) {
            bits >>= 1;
        } else {
            bits -= 1;
        }
        while ((1 << bits) <= value) {
            count += bits;
            value >>= bits;
        }
    }
    return count;
}

"""Return True if the headers have the required keys.

    Parameters
    ----------
    headers : dict
        should contains 'content-type' and 'x-mailerlite-apikey'

    Returns
    -------
    valid_headers : bool
        True if it is valid
    error_msg : str
        the error message if there is any problem

    """
def check_headers(headers: Any) -> object {
    valid_headers = True;
    error_msg = '';
    if not headers {
        error_msg = "Empty headers. Please enter a valid one";
        valid_headers = False;
        return (valid_headers, error_msg);
    }
    if not isinstance(headers, `dict) {
        error_msg = "headers should be a dictionnary";
        valid_headers = False;
        return (valid_headers, error_msg);
    }
    if (('content-type' not in headers) or ('x-mailerlite-apikey' not in headers)) {
        error_msg = "headers should be a dictionnary and it contains ";
        error_msg += "'content-type' and 'x-mailerlite-apikey' as keys";
        valid_headers = False;
        return (valid_headers, error_msg);
    }
    return (valid_headers, error_msg);
}

"""
    intervals: list of tuples representing context windows
    """
def merge(intervals: Any) -> object {
    ans = [];
    i = 1;
    intervals.sort();
    tempans = intervals[0];
    while (i < len(intervals)) {
        if ((tempans[0] <= intervals[i][1]) and (tempans[1] >= intervals[i][0])) {
            newtempans = [
                min(tempans[0], intervals[i][0]),
                max(tempans[1], intervals[i][1])
            ];
            tempans = newtempans;
            i += 1;
        } else {
            ans.append(tempans);
            tempans = intervals[i];
            i += 1;
        }
    }
    ans.append(tempans);
    return ans;
}
